head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gTypeMsg = "";
scwin.rtn;
scwin.gType;
scwin.gUsrId = js_id;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.myFormNmList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF51010.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert("사용자서식그룹 명칭이 " + scwin.gTypeMsg + " 되었습니다.");

        // 사용자 서식 목록 을  다시 불러옴
        await scwin.myFormNmList();
        $c.frame.path("../").fn_myFormNmList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF51010.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert("사용자서식그룹 명칭이 " + scwin.gTypeMsg + "이(가) 실패하였습니다.");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF51010.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function() {
    try {
        scwin.gType = "DI";
        scwin.gTypeMsg = "삭제";
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF51010.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name btn_update_onclick
 * @description 「변경」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_update_onclick = async function() {
    try {
        scwin.gType = "U";
        scwin.gTypeMsg = "변경";
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF51010.btn_update_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF51010.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_updateList",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_updateList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name myFormNmList
 * @description 사용자서식 명칭 리스트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.myFormNmList = async function() {
    // 사용자서식 명칭 리스트
    const sbmOptions = {
        id : "sbm_dts_MyFormNmList",
        action : "/MyFormPage.do",
        ref : "",
        target : "dts_MyFormNmList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    await scwin.setHeader();
    if (!scwin.cntRowCheck(dts_MyFormNmList)) {
        await $c.win.alert("변경할 사용자 서식 그룹을 선택하여 주십시요");
    } else {
        let gMsgCnt = 0;
        let gCheckCnt = 0;
        let tmpInt = 1;
        scwin.rtn = confirm("사용자 서식 그룹 명칭을 변경 하시겠습니까?");
        if (scwin.rtn === 1) // [확인] 버튼이 눌려졌을 경우

        {
            dts_updateList.setBroadcast(false);
            for (let i = 1; i <= dts_MyFormNmList.getRowCount(); i++) {
                if (dts_MyFormNmList.getCellData(i, "CHK_FLAG") === 1) {
                    if (($c.stf.getStringSize(dts_MyFormNmList.getCellData(i, "AFTER_MYFORM_NM")) - 20) > 0) {
                        gCheckCnt++;
                    }
                    dts_updateList.insertRow();
                    dts_updateList.setCellData(tmpInt, "AFTER_MYFORM_NM", dts_MyFormNmList.getCellData(i, "AFTER_MYFORM_NM"));
                    dts_updateList.setCellData(tmpInt, "USR_FORM_GRP_SEQ", dts_MyFormNmList.getCellData(i, "USR_FORM_GRP_SEQ"));
                    dts_updateList.setCellData(tmpInt, "USR_ID", scwin.gUsrId);
                    tmpInt++;
                }
            }
            dts_updateList.setBroadcast(true, true);
            if (gCheckCnt > 0) {
                await $c.win.alert("[ 변경후 ] 항목의 값이  [20 ] byte 가 넘는 명칭이 있습니다. \n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
            } else {
                trs_Save.KeyName = "toinb_dataid4";
                const sbmOptions = {
                    id : "sbm_trs_Save",
                    action : "/MyFormPage.do",
                    ref : "dts_updateList",
                    target : "trs_Save=body.content",
                    isProcessMsg : false
                };

                const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
            }
        }
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    await scwin.setHeader();
    if (!scwin.cntRowCheck(dts_MyFormNmList)) {
        await $c.win.alert("삭제할 사용자 서식 그룹을 선택하여 주십시요");
    } else {
        let gMsgCnt = 0;
        let gCheckCnt = 0;
        let tmpInt = 1;
        scwin.rtn = confirm("사용자 서식 그룹을 삭제 하시겠습니까? \n서식목록도 함께 삭제됩니다.");
        if (scwin.rtn === 1) // [확인] 버튼이 눌려졌을 경우

        {
            dts_updateList.setBroadcast(false);
            for (let i = 1; i <= dts_MyFormNmList.getRowCount(); i++) {
                if (dts_MyFormNmList.getCellData(i, "CHK_FLAG") === 1) {
                    dts_updateList.insertRow();
                    dts_updateList.setCellData(tmpInt, "AFTER_MYFORM_NM", dts_MyFormNmList.getCellData(i, "AFTER_MYFORM_NM"));
                    dts_updateList.setCellData(tmpInt, "USR_FORM_GRP_SEQ", dts_MyFormNmList.getCellData(i, "USR_FORM_GRP_SEQ"));
                    dts_updateList.setCellData(tmpInt, "USR_ID", scwin.gUsrId);
                    tmpInt++;
                }
            }
            dts_updateList.setBroadcast(true, true);
            trs_Save.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/MyFormPage.do",
                ref : "dts_updateList",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name cntRowCheck
 * @description cnt Row Check 처리
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.cntRowCheck = function(sval) {
    let cCnt = 0;
    for (i = 1; i <= sval.getRowCount(); i++) {
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};
